// File: src/integrations/supabase/client.ts
// This file is automatically generated. Do not edit it directly.
import { createClient } from "@supabase/supabase-js";
import type { Database } from "./types";

// IMPORTANT: Use .env (Lovable/Vite)
// Required (any ONE of these anon-key vars works):
//   VITE_SUPABASE_URL="https://YOURPROJECT.supabase.co"
//   VITE_SUPABASE_ANON_KEY="YOUR_ANON_KEY"
//   VITE_SUPABASE_PUBLISHABLE_KEY="YOUR_ANON_KEY"   (legacy name used in this repo)
// Optional aliases supported:
//   VITE_PUBLIC_SUPABASE_URL, VITE_SUPABASE_KEY
const SUPABASE_URL =
  (import.meta.env.VITE_SUPABASE_URL as string) ||
  (import.meta.env.VITE_PUBLIC_SUPABASE_URL as string) ||
  "";

const SUPABASE_ANON_KEY =
  (import.meta.env.VITE_SUPABASE_ANON_KEY as string) ||
  (import.meta.env.VITE_SUPABASE_PUBLISHABLE_KEY as string) ||
  (import.meta.env.VITE_SUPABASE_KEY as string) ||
  "";

if (!SUPABASE_URL || !SUPABASE_ANON_KEY) {
  console.error(
    "Missing Supabase env vars. Set VITE_SUPABASE_URL and VITE_SUPABASE_ANON_KEY (or VITE_SUPABASE_PUBLISHABLE_KEY) in your .env",
  );
}

export const supabase = createClient<Database>(SUPABASE_URL, SUPABASE_ANON_KEY, {
  auth: {
    storage: localStorage,
    persistSession: true,
    autoRefreshToken: true,
  },
});
